import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// +++ Arrange context providers +++
const mockCart = {
  items: [{ id: '1', name: 'Luggage', price: 99.99 }],
  total: 99.99,
  clearCart: vi.fn()
};

const mockProcessPayment = vi.fn();

const renderCheckout = (props = {}) => {
  return render(
    <CartContext.Provider value={mockCart}>
      <PaymentContext.Provider value={{ processPayment: mockProcessPayment }}>
        <Checkout {...props} />
      </PaymentContext.Provider>
    </CartContext.Provider>
  );
};

describe('Checkout - Happy Path', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-12345' });
  });

  it('completes full checkout flow from shipping to confirmation', async () => {
    const user = userEvent.setup();
    const onComplete = vi.fn();
    renderCheckout({ onComplete });

    // Shipping step
    await user.type(screen.getByLabelText(/street address/i), '123 Unseen University');
    await user.type(screen.getByLabelText(/city/i), 'Ankh-Morpork');
    await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
    await user.type(screen.getByLabelText(/zip code/i), '12345');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Payment step
    await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
    await user.type(screen.getByLabelText(/expiry/i), '12/25');
    await user.type(screen.getByLabelText(/cvv/i), '123');
    await user.type(screen.getByLabelText(/name on card/i), 'Ponder Stibbons');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Review step
    expect(screen.getByText(/luggage/i)).toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: /place order/i }));

    // Confirmation
    await waitFor(() => {
      expect(screen.getByRole('status')).toHaveTextContent('ORD-12345');
    });
    expect(onComplete).toHaveBeenCalledWith('ORD-12345');
  });
});

describe('Checkout - Validation', () => {
  it('shows validation errors for empty shipping fields', async () => {
    const user = userEvent.setup();
    renderCheckout();

    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByRole('alert')).toHaveTextContent(/street address is required/i);
    expect(screen.getByLabelText(/street/i)).toHaveAttribute('aria-invalid', 'true');
  });

  it('validates ZIP code format', async () => {
    const user = userEvent.setup();
    renderCheckout();

    await user.type(screen.getByLabelText(/zip code/i), 'MELON');
    await user.click(screen.getByRole('button', { name: /continue/i }));

    expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
  });
});

describe('Checkout - Error Recovery', () => {
  it('displays payment error and allows retry', async () => {
    mockProcessPayment.mockRejectedValueOnce(new Error('Insufficient cheese'));
    // ... navigate to review, click place order

    await waitFor(() => {
      expect(screen.getByRole('alert')).toHaveTextContent(/insufficient cheese/i);
    });
    expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
  });
});

describe('Checkout - Edge Cases', () => {
  it('shows empty cart message when no items', () => {
    mockCart.items = [];
    renderCheckout();
    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
  });
});

describe('Checkout - Accessibility', () => {
  it('has no axe violations', async () => {
    const { container } = renderCheckout();
    expect(await axe(container)).toHaveNoViolations();
  });
});
